Here is the commit message:
PCI: rockchip: Fix rockchip_pcie_ep_assert_intx() bitwise
 operations

Currently the bitwise operations on the u16 variable 'status' with
the setting ROCKCHIP_PCIE_EP_CMD_STATUS_IS are incorrect because
ROCKCHIP_PCIE_EP_CMD_STATUS_IS is 1UL<<19 which is wider than the
u16 variable.

Fix this by making status a u32.

Fixes: cf590b078391 ("PCI: rockchip: Add EP driver for Rockchip PCIe controller")
Signed-off-by: Colin Ian King <colin.king@canonical.com>
Signed-off-by: Lorenzo Pieralisi <lorenzo.pieralisi@arm.com>
Reviewed-by: Mukesh Ojha <mojha@codeaurora.org>
Acked-by: Shawn Lin <shawn.lin@rock-chips.com>

Here is the root cause:
The bug was caused by using a `u16` variable (`status`) for bitwise operations involving `ROCKCHIP_PCIE_EP_CMD_STATUS_IS`, which is defined as `1UL << 19`. Since `1UL << 19` exceeds the maximum value that a `u16` can hold (65535), this led to incorrect behavior and potential overflow during the operations. Changing `status` to `u32` resolves this issue by providing sufficient range to handle the bitwise operations correctly.

Here is the patch:

 static void rockchip_pcie_ep_assert_intx(struct rockchip_pcie_ep *ep, u8 fn,
 					 u8 intx, bool is_asserted)
 {
 	struct rockchip_pcie *rockchip = &ep->rockchip;
 	u32 r = ep->max_regions - 1;
 	u32 offset;
-	u16 status;
+	u32 status;
 	u8 msg_code;

 	if (unlikely(ep->irq_pci_addr != ROCKCHIP_PCIE_EP_PCI_LEGACY_IRQ_ADDR ||
 		     ep->irq_pci_fn != fn)) {
 		rockchip_pcie_prog_ep_ob_atu(rockchip, fn, r,
 					     AXI_WRAPPER_NOR_MSG,
 					     ep->irq_phys_addr, 0, 0);
 		ep->irq_pci_addr = ROCKCHIP_PCIE_EP_PCI_LEGACY_IRQ_ADDR;
 		ep->irq_pci_fn = fn;
 	}

 	intx &= 3;
 	if (is_asserted) {
 		ep->irq_pending |= BIT(intx);
 		msg_code = ROCKCHIP_PCIE_MSG_CODE_ASSERT_INTA + intx;
 	} else {
 		ep->irq_pending &= ~BIT(intx);
 		msg_code = ROCKCHIP_PCIE_MSG_CODE_DEASSERT_INTA + intx;
 	}

 	status = rockchip_pcie_read(rockchip,
 				    ROCKCHIP_PCIE_EP_FUNC_BASE(fn) +
 				    ROCKCHIP_PCIE_EP_CMD_STATUS);
 	status &= ROCKCHIP_PCIE_EP_CMD_STATUS_IS;

 	if ((status != 0) ^ (ep->irq_pending != 0)) {
 		status ^= ROCKCHIP_PCIE_EP_CMD_STATUS_IS;
 		rockchip_pcie_write(rockchip, status,
 				    ROCKCHIP_PCIE_EP_FUNC_BASE(fn) +
 				    ROCKCHIP_PCIE_EP_CMD_STATUS);
 	}

 	offset =
 	   ROCKCHIP_PCIE_MSG_ROUTING(ROCKCHIP_PCIE_MSG_ROUTING_LOCAL_INTX) |
 	   ROCKCHIP_PCIE_MSG_CODE(msg_code) | ROCKCHIP_PCIE_MSG_NO_DATA;
 	writel(0, ep->irq_cpu_addr + offset);
 }



